                )

        logger.info(f"  Computing K_eff for all C(15,3)=455 panels on {ds}...")
        panels = compute_all_panel_keffs(mi_mat, ds)
        keff_per_panel[ds] = panels

        keff_values = [p["keff"] for p in panels.values()]
        logger.info(
